// Normalise both triggers to { user_id, ai_note_id, source }.
//  - Schedule trigger -> user_id null -> batch over recently-active users.
//  - Webhook callers:
//      * Supabase DB webhook on mobile_checkins INSERT -> body.record.app_user_id
//      * SOAP & Note QA workflow (after a session note)  -> body.ai_note_id
// A webhook call with no resolvable identifier is dropped (never fall through
// to a full batch run from a malformed webhook).
const results = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  const isWebhook = j.body !== undefined || j.headers !== undefined;
  const b = j.body ?? {};
  const rec = b.record ?? b;
  const userId = Number(rec.app_user_id ?? rec.user_id ?? NaN);
  const noteId = Number(rec.ai_note_id ?? NaN);
  if (Number.isInteger(userId) && userId > 0) {
    results.push({ json: { user_id: userId, ai_note_id: null, source: 'checkin' } });
  } else if (Number.isInteger(noteId) && noteId > 0) {
    results.push({ json: { user_id: null, ai_note_id: noteId, source: 'note' } });
  } else if (!isWebhook) {
    results.push({ json: { user_id: null, ai_note_id: null, source: 'daily' } });
  }
}
return results;

